// hooks/useSocket.js - Updated for Cloudflare Workers
import { useEffect, useRef, useState } from 'react';

const WS_URL = 'wss://carcare-realtime.brianbakari22.workers.dev';

export const useSocket = () => {
  const [isConnected, setIsConnected] = useState(false);
  const socketRef = useRef(null);

  useEffect(() => {
    // Connect to Cloudflare WebSocket
    const ws = new WebSocket(`${WS_URL}/ws/driver`);
    socketRef.current = ws;

    ws.onopen = () => {
      console.log('✅ WebSocket connected to Cloudflare');
      setIsConnected(true);
    };

    ws.onclose = () => {
      console.log('❌ WebSocket disconnected');
      setIsConnected(false);
      // Attempt to reconnect after 5 seconds
      setTimeout(() => {
        if (socketRef.current?.readyState !== WebSocket.OPEN) {
          console.log('🔄 Attempting to reconnect...');
          const newWs = new WebSocket(`${WS_URL}/ws/driver`);
          socketRef.current = newWs;
        }
      }, 5000);
    };

    ws.onerror = (error) => {
      console.error('WebSocket error:', error);
    };

    return () => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.close();
      }
    };
  }, []);

  // Update driver location
  const updateDriverLocation = (lat, lng) => {
    if (socketRef.current?.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({
        type: 'location',
        location: { lat, lng }
      }));
    }
  };

  // Go online
  const goOnline = () => {
    if (socketRef.current?.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({
        type: 'status',
        status: 'online'
      }));
    }
  };

  // Go offline
  const goOffline = () => {
    if (socketRef.current?.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({
        type: 'status',
        status: 'offline'
      }));
    }
  };

  // Update booking status
  const updateBookingStatus = (bookingId, status) => {
    if (socketRef.current?.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({
        type: 'booking-status',
        bookingId,
        status
      }));
    }
  };

  // Join booking room
  const joinBookingRoom = (bookingId) => {
    if (socketRef.current?.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({
        type: 'join-booking',
        bookingId
      }));
    }
  };

  // Subscribe to driver
  const subscribeToDriver = (driverId) => {
    if (socketRef.current?.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({
        type: 'track-driver',
        driverId
      }));
    }
  };

  // Unsubscribe from driver
  const unsubscribeFromDriver = (driverId) => {
    if (socketRef.current?.readyState === WebSocket.OPEN) {
      socketRef.current.send(JSON.stringify({
        type: 'stop-tracking',
        driverId
      }));
    }
  };

  // Event listeners (simplified for Cloudflare)
  const onDriverLiveLocation = (callback) => {
    const handler = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'location-update') {
        callback(data);
      }
    };
    socketRef.current?.addEventListener('message', handler);
    return () => socketRef.current?.removeEventListener('message', handler);
  };

  const onBookingStatusChanged = (callback) => {
    const handler = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'booking-update') {
        callback(data);
      }
    };
    socketRef.current?.addEventListener('message', handler);
    return () => socketRef.current?.removeEventListener('message', handler);
  };

  const onNewNotification = (callback) => {
    const handler = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'notification') {
        callback(data);
      }
    };
    socketRef.current?.addEventListener('message', handler);
    return () => socketRef.current?.removeEventListener('message', handler);
  };

  const onDriverStatusChange = (callback) => {
    const handler = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'driver-status') {
        callback(data);
      }
    };
    socketRef.current?.addEventListener('message', handler);
    return () => socketRef.current?.removeEventListener('message', handler);
  };

  return {
    isConnected,
    updateDriverLocation,
    goOnline,
    goOffline,
    updateBookingStatus,
    joinBookingRoom,
    subscribeToDriver,
    unsubscribeFromDriver,
    onDriverLiveLocation,
    onBookingStatusChanged,
    onNewNotification,
    onDriverStatusChange
  };
};
